from jinja2 import DictLoader, Environment, select_autoescape

TEMPLATES = {
"base.html": """<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>ReadTrackr</title><style>:root{--i:#20202a;--p:#fffdf8;--a:#6a4c93;--l:#e8e1d8}*{box-sizing:border-box}body{margin:0;background:var(--p);color:var(--i);font:16px system-ui,sans-serif}header{padding:18px 5vw;display:flex;justify-content:space-between;border-bottom:1px solid var(--l)}header>a{font-weight:800;color:var(--i)}a{color:var(--a);text-decoration:none}nav{display:flex;gap:15px;align-items:center}nav form{margin:0}button,.button{border:0;background:var(--a);color:white;padding:10px 14px;border-radius:8px;font:inherit;cursor:pointer}main{max-width:1050px;margin:auto;padding:34px 5vw}.title{display:flex;justify-content:space-between}.stats,.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px}.stats article,.card,.recommendation{background:white;border:1px solid var(--l);border-radius:12px;padding:18px}.stats b{display:block;font-size:2rem}.card{color:var(--i);display:flex;gap:12px}.card strong,.card small{display:block}small,.muted{color:#716b72}.cover{width:54px;height:78px;flex:none;border-radius:6px;background:#e8dff0;display:grid;place-items:center;font-size:1.7rem;overflow:hidden}.cover img{width:100%;height:100%;object-fit:cover}.large{width:130px;height:190px}.detail{display:flex;gap:25px}.form{display:grid;gap:16px;max-width:600px}label{display:grid;gap:6px;font-weight:600}input,select,textarea{font:inherit;padding:10px;border:1px solid var(--l);border-radius:7px}textarea{min-height:130px}.auth{max-width:380px;margin:10vh auto}.filters{display:flex;gap:10px;margin:20px 0}.filters input{flex:1}table{width:100%;border-collapse:collapse;margin:16px 0}td,th{text-align:left;padding:8px;border-bottom:1px solid var(--l)}.error{color:#a12222}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions form{margin:0}.recommendation{display:grid;grid-template-columns:80px 1fr;gap:16px;margin:16px 0}.recommendation .cover{width:80px;height:115px}@media(max-width:650px){header{display:block;padding:14px 5vw}nav{margin-top:14px;display:flex;flex-wrap:wrap;gap:12px;align-items:center}nav a{display:block;font-size:.9rem;white-space:nowrap}nav button{padding:7px 10px;font-size:.9rem}.filters{flex-wrap:wrap}.filters input{min-width:100%}.recommendation{grid-template-columns:60px 1fr}.recommendation .cover{width:60px;height:88px}}</style></head><body><header><a href='/'>ReadTrackr</a>{% if request.session.get('user') %}<nav><a href='/library'>Library</a><a href='/metadata'>Covers</a><a href='/recommendations'>For you</a><a href='/import'>Import</a><a href='/export/csv'>CSV</a><form method='post' action='/logout'><button>Log out</button></form></nav>{% endif %}</header><main>{% block content %}{% endblock %}</main></body></html>""",
"login.html": "{% extends 'base.html' %}{% block content %}<section class='auth'><h1>Welcome back</h1>{% if error %}<p class='error'>{{error}}</p>{% endif %}<form method='post'><label>Username<input name='username' required autofocus></label><label>Password<input name='password' type='password' required></label><button>Sign in</button></form></section>{% endblock %}",
"cards.html": "<div class='grid'>{% for entry in entries %}<a class='card' href='/books/{{entry.book.id}}'><div class='cover'>{% if entry.book.thumbnail_url %}<img src='{{entry.book.thumbnail_url}}'>{% else %}📚{% endif %}</div><div><strong>{{entry.book.title}}</strong><small>{{entry.book.authors}}</small><small>{{entry.status.replace('_',' ')}} {% if entry.rating %}· {{'★' * entry.rating}}{% endif %}</small></div></a>{% else %}<p class='muted'>Nothing here yet.</p>{% endfor %}</div>",
"dashboard.html": "{% extends 'base.html' %}{% block content %}<div class='title'><div><p class='muted'>YOUR READING LIFE</p><h1>Dashboard</h1></div><a class='button' href='/books/new'>Add a book</a></div><div class='stats'><article><b>{{entries|selectattr('status','equalto','read')|list|length}}</b><span>books read</span></article><article><b>{{current|length}}</b><span>currently reading</span></article><article><b>{{entries|selectattr('rating')|list|length}}</b><span>rated books</span></article></div><h2>Current reads</h2>{% set entries=current %}{% include 'cards.html' %}<h2>Recently read</h2><p class='muted'>Showing your six most recently read books. <a href='/library'>View your full library →</a></p>{% set entries=recent %}{% include 'cards.html' %}{% endblock %}",
"library.html": "{% extends 'base.html' %}{% block content %}<div class='title'><h1>Library</h1><a class='button' href='/books/new'>Add a book</a></div><form class='filters'><input name='q' value='{{q}}' placeholder='Search title or author'><select name='status'><option value=''>All statuses</option>{% for s in ['read','currently_reading','want_to_read','paused','abandoned','dismissed','not_interested'] %}<option value='{{s}}' {% if selected==s %}selected{% endif %}>{{s.replace('_',' ')}}</option>{% endfor %}</select><button>Filter</button></form>{% include 'cards.html' %}{% endblock %}",
"book_form.html": "{% extends 'base.html' %}{% block content %}<h1>Add a book</h1><form class='form' method='post'><label>Title<input name='title' required></label><label>Author<input name='authors'></label><label>Status<select name='status'>{% for s in ['want_to_read','currently_reading','read','paused','abandoned'] %}<option value='{{s}}'>{{s.replace('_',' ')}}</option>{% endfor %}</select></label><label>Rating<input name='rating' type='number' min='1' max='5'></label><button>Add to library</button></form>{% endblock %}",
"book.html": "{% extends 'base.html' %}{% block content %}<article class='detail'><div class='cover large'>📚</div><div><p class='muted'>{{entry.status.replace('_',' ')}}</p><h1>{{book.title}}</h1><p>{{book.authors}}</p></div></article><form class='form' method='post'><label>Status<select name='status'>{% for s in ['read','currently_reading','want_to_read','paused','abandoned','dismissed','not_interested'] %}<option value='{{s}}' {% if entry.status==s %}selected{% endif %}>{{s.replace('_',' ')}}</option>{% endfor %}</select></label><label>Rating<select name='rating'><option value=''></option>{% for r in range(1,6) %}<option value='{{r}}' {% if entry.rating==r %}selected{% endif %}>{{r}} stars</option>{% endfor %}</select></label><label>Private notes<textarea name='notes'>{{entry.private_notes or ''}}</textarea></label><button>Save changes</button></form>{% endblock %}",
"import.html": "{% extends 'base.html' %}{% block content %}<h1>Import Goodreads CSV</h1><p class='muted'>Upload your Goodreads export, review it, then import it. Re-importing updates matching books.</p>{% if not preview and not summary %}<form class='form' method='post' action='/import/preview' enctype='multipart/form-data'><input type='file' name='csv_file' accept='.csv,text/csv' required><button>Preview import</button></form>{% endif %}{% if preview %}<p><b>{{total}}</b> rows found.</p><table><tr><th>Title</th><th>Author</th><th>Shelf</th><th>Rating</th></tr>{% for row in preview %}<tr><td>{{row['Title']}}</td><td>{{row['Author']}}</td><td>{{row['Exclusive Shelf']}}</td><td>{{row['My Rating']}}</td></tr>{% endfor %}</table><form method='post' action='/import/commit'><button>Import {{total}} books</button></form>{% endif %}{% if summary %}<h2>Import complete</h2><p>Added {{summary.added}}, updated {{summary.updated}}, skipped {{summary.skipped}}.</p><a class='button' href='/library'>View library</a>{% endif %}{% endblock %}",
"metadata.html": "{% extends 'base.html' %}{% block content %}<h1>Book covers & metadata</h1><p class='muted'>{{missing}} books still need a cover. Each refresh checks up to 25 books through Google Books and caches the result locally.</p>{% if summary %}<p><b>Refresh complete:</b> checked {{summary.checked}}, updated {{summary.updated}}, not found {{summary.not_found}}, errors {{summary.errors}}.</p>{% endif %}<form method='post' action='/metadata/refresh'><button>{% if missing %}Refresh next batch of covers{% else %}Check covers again{% endif %}</button></form>{% endblock %}",
"recommendations.html": "{% extends 'base.html' %}{% block content %}<div class='title'><div><h1>For you</h1><p class='muted'>Manual refreshes use your ratings and reading history. Recommendation reasons are spoiler-free.</p></div><form method='post' action='/recommendations/refresh'><button>Refresh recommendations</button></form></div>{% if error %}<p class='error'>{{error}}</p>{% endif %}{% for rec in recs %}<article class='recommendation'><div class='cover'>{% if rec.book.thumbnail_url %}<img src='{{rec.book.thumbnail_url}}'>{% else %}📚{% endif %}</div><div><p class='muted'>{{(rec.score * 100)|round|int}}% match</p><h2>{{rec.book.title}}</h2><p>{{rec.book.authors}}</p><p>{{rec.reason}}</p>{% if rec.matched_preferences %}<small>Matches: {{rec.matched_preferences}}</small>{% endif %}<div class='actions'><form method='post' action='/recommendations/{{rec.id}}/want_to_read'><button>Want to read</button></form><form method='post' action='/recommendations/{{rec.id}}/dismissed'><button>Dismiss</button></form><form method='post' action='/recommendations/{{rec.id}}/not_interested'><button>Not interested</button></form></div></div></article>{% else %}<p class='muted'>No recommendations yet. Add ratings, refresh covers, then refresh recommendations.</p>{% endfor %}{% endblock %}"
}
environment = Environment(loader=DictLoader(TEMPLATES), autoescape=select_autoescape())
